// Para onde vao os alertas. REMETENTE tem de ser a conta da credencial de email (SMTP).
const PARA = 'cesarfsaraujo@gmail.com';
const REMETENTE = 'cesarfsaraujo@gmail.com';
const N8N = 'https://olivedrab-cat-986392.hostingersite.com';
const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const quando = new Date().toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon' });
const tabela = linhas => '<table style="border-collapse:collapse;font:14px/1.5 system-ui,sans-serif">' + linhas.filter(l => l[1] !== undefined && l[1] !== null && l[1] !== '').map(([k, v]) =>
  '<tr><td style="padding:4px 14px 4px 0;color:#666;vertical-align:top">' + esc(k) + '</td><td style="padding:4px 0">' + (String(v).startsWith('http') ? '<a href="' + esc(v) + '">abrir no n8n</a>' : esc(v)) + '</td></tr>').join('') + '</table>';

// Um so formato para os dois caminhos: (1) erro de qualquer workflow — Error Trigger,
// ligado pelo settings.errorWorkflow de cada um; (2) falha silenciosa avisada pelo Inbound
// (a IA nao respondeu, ou respondeu estragado) — que no n8n aparece como "success".
const j = $input.first().json || {};
let assunto, linhas;
if (j.execution || j.trigger) {
  const ex = j.execution || {}, wf = j.workflow || {}, err = ex.error || (j.trigger || {}).error || {};
  assunto = '⚠️ CAV: falhou ' + (wf.name || 'um workflow');
  linhas = [['Workflow', wf.name], ['Nó', ex.lastNodeExecuted || (err.node || {}).name], ['Erro', err.message || err.description],
    ['Quando', quando], ['Execução', ex.url || (ex.id && wf.id ? N8N + '/workflow/' + wf.id + '/executions/' + ex.id : '')]];
} else {
  const TIPOS = { ia_sem_resposta: 'A IA não respondeu — provavelmente o limite diário do Gemini', ia_resposta_invalida: 'A IA devolveu uma resposta estragada — nada foi gravado' };
  assunto = '⚠️ CAV: ' + (TIPOS[j.tipo] || j.tipo || 'falha');
  linhas = [['O que aconteceu', TIPOS[j.tipo] || j.tipo], ['Comercial', j.comercial], ['Disse', j.transcricao], ['Detalhe', j.erro],
    ['Quando', quando], ['Execução', j.execucao ? N8N + '/workflow/bSTGP7PErDam8WPE/executions/' + j.execucao : '']];
}
const html = '<p style="font:15px system-ui,sans-serif"><b>' + esc(assunto) + '</b></p>' + tabela(linhas)
  + (j.execution || j.trigger ? '' : '<p style="font:12px system-ui,sans-serif;color:#888">O comercial já viu um aviso no Terminal. Este email é só para ti.</p>');
return [{ json: { para: PARA, remetente: REMETENTE, assunto, html } }];
